from pathlib import Path
from dataclasses import dataclass
from typing import Optional

from satyrn_evals.errors import UsageError

class RunRecordError(UsageError):
    """Raised when a run record is invalid or fails the gate."""
    pass

@dataclass
class RunRecord:
    version: int
    task: str
    task_tree_sha256: str
    arm: str
    model: str
    condition: str
    n: int
    mode: str
    max_minutes: int
    stop_rule: str
    decision_rule: str
    previous_result: Optional[Path] = None

def load_run_record(path: Path) -> RunRecord:
    import json

    try:
        with path.open("r") as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        raise RunRecordError(f"not a JSON object: {path}") from e
    if not isinstance(data, dict):
        raise RunRecordError(f"not a JSON object: {path}")

    # Expected fields and types
    expected_fields = {
        "version": int,
        "task": str,
        "task_tree_sha256": str,
        "arm": str,
        "model": str,
        "condition": str,
        "n": int,
        "mode": str,
        "max_minutes": int,
        "stop_rule": str,
        "decision_rule": str,
        "previous_result": (type(None), Path),
    }

    record_data = {}
    for field_name, expected_type in expected_fields.items():
        if field_name not in data:
            raise RunRecordError(f"missing field: {field_name}")
        value = data[field_name]
        # Handle previous_result specially because it can be null or a string path
        if field_name == "previous_result":
            if value is None:
                record_data[field_name] = None
            else:
                if not isinstance(value, str):
                    raise RunRecordError(f"previous_result has the wrong type")
                record_data[field_name] = Path(value)
            continue

        if isinstance(expected_type, tuple):
            if not isinstance(value, expected_type):
                raise RunRecordError(f"{field_name} has the wrong type")
        else:
            if not isinstance(value, expected_type):
                raise RunRecordError(f"{field_name} has the wrong type")
        record_data[field_name] = value

    # Additional validation rules
    condition = record_data["condition"]
    if condition not in {"cold", "warm"}:
        raise RunRecordError(f"condition must be cold or warm")

    mode = record_data["mode"]
    if mode not in {"attended", "batch"}:
        raise RunRecordError(f"mode must be attended or batch")

    n = record_data["n"]
    max_minutes = record_data["max_minutes"]
    if mode == "attended":
        if n > 8:
            raise RunRecordError("attended exceeds n limit")
        if max_minutes > 60:
            raise RunRecordError("attended exceeds max_minutes limit")
    else:  # batch
        if n > 12:
            raise RunRecordError("batch exceeds n limit")
        if max_minutes > 720:
            raise RunRecordError("batch exceeds max_minutes limit")

    stop_rule = record_data["stop_rule"]
    if not stop_rule or not stop_rule.strip():
        raise RunRecordError("stop_rule is empty")

    decision_rule = record_data["decision_rule"]
    if not decision_rule or not decision_rule.strip():
        raise RunRecordError("decision_rule is empty")

    return RunRecord(**record_data)

def gate(record: RunRecord, *, previous_result_committed: Optional[bool] = None) -> None:
    """Enforce cadence rules on a loaded record.

    Raises:
        RunRecordError: If the record fails validation.
    """
    if record.previous_result is not None:
        if previous_result_committed is None:
            # Compute by checking if the file exists
            import subprocess
            try:
                result = subprocess.run(
                    ["git", "ls-files", "--error-unmatch", str(record.previous_result)],
                    capture_output=True,
                    text=True,
                )
                previous_result_committed = result.returncode == 0
            except Exception as e:
                raise RunRecordError(f"failed to check previous result: {e}")
        if not previous_result_committed:
            raise RunRecordError("previous_result not committed")

    # Enforce mode-specific limits
    if record.mode == "attended":
        if record.n > 8:
            raise RunRecordError("attended exceeds n limit")
        if record.max_minutes > 60:
            raise RunRecordError("attended exceeds max_minutes limit")
    elif record.mode == "batch":
        if record.n > 12:
            raise RunRecordError("batch exceeds n limit")
        if record.max_minutes > 720:
            raise RunRecordError("batch exceeds max_minutes limit")

    return None"}
